    const auto before=encode_common_state(f.common.state());auto page=query_task_message_handoffs(f.common,f.tasks,f.catalog,*f.shared,*f.tasks.message_handoffs);require(page.ok&&page.value.find("rows")->as<BoundaryValue::Array>()->size()==1&&compare_boundary(before,encode_common_state(f.common.state())).exact(),"actual participant page pure");auto value=encode_task_message_handoffs(*f.tasks.message_handoffs);auto decoded=decode_task_message_handoffs(value);require(decoded.ok&&validate_task_message_handoffs(f.common,f.tasks,f.catalog,*f.shared,decoded.value).ok,"JSON cold source and observer index");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);auto state=*f.tasks.message_handoffs;require(visit_task_message_handoffs_checkpoint(writer,state).ok&&writer.finish().ok,"binary encode");TaskMessageHandoffState restored;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(bytes));require(visit_task_message_handoffs_checkpoint(reader,restored).ok&&reader.finish().ok&&restored.observed_by==state.observed_by,"binary observer index rebuild");
    auto forged=state;forged.receipts.find(fact)->recipient_actor_id="stranger";require(!validate_task_message_handoffs(f.common,f.tasks,f.catalog,*f.shared,forged).ok,"forged recipient rejected");forged=state;forged.observed_by["sender"]={fact};require(!validate_task_message_handoffs(f.common,f.tasks,f.catalog,*f.shared,forged).ok,"forged notification index rejected");forged=state;forged.receipts.find(fact)->tick=13;require(!validate_task_message_handoffs(f.common,f.tasks,f.catalog,*f.shared,forged).ok,"future arrival rejected");forged=state;forged.receipts={};forged.observed_by.clear();require(!validate_task_message_handoffs(f.common,f.tasks,f.catalog,*f.shared,forged).ok,"orphan arrival header rejected");require(!validate_task_message_handoff_layout(f.common,false,{},nullptr).ok,"old profile rejects new fact");
    auto repeated=value;repeated.as<BoundaryValue::Dict>()->push_back({"version",BoundaryValue{Integer{1}}});require(!decode_task_message_handoffs(repeated).ok,"duplicate field rejects");auto unknown=value;unknown.find("version")->data=Integer{2};require(!decode_task_message_handoffs(unknown).ok,"unknown version rejects");
