    Fixture late;late.finish(late.start("accept_offer"));auto action=late.start("deliver_message");late.common.state().next_instance_id=std::numeric_limits<Integer>::max()-1;const auto original=encode_common_state(late.common.state());const auto tasks=late.tasks;auto saved=late.common.begin_savepoint();require(saved.ok,"component savepoint");auto failed=finish_task_action(late.common,late.tasks,late.social,late.catalog,late.interaction,late.ic,late.access,action,late.common.tick()+1);require(!failed.ok&&failed.error.original.code=="InstanceIdOverflow"&&late.common.count("bag:recipient","letter",{{Owner::Kind::actor,"recipient",{}}}).value==1&&late.tasks.message_handoffs->receipts.empty(),"late receipt ID failure is after actual letter transfer");require(late.common.rollback_savepoint(saved.value).ok,"component common rollback");late.tasks=tasks;require(compare_boundary(original,encode_common_state(late.common.state())).exact()&&late.tasks.message_handoffs->receipts.empty(),"component boundary restores original letter and no false receipt");
